     1|/**
     2| * IVX Canonical Members Sync
     3| *
     4| * One canonical member row in public.members for every landing registration,
     5| * regardless of which capture path it arrived through:
     6| *   - /api/members/register            (landing free-member signup → auth.users + profiles)
     7| *   - /api/ivx/leads/capture           (waitlist / zone capture / funnel mirror → durable lead store)
     8| *   - waitlist table inserts           (expo app + legacy landing waitlist)
     9| *   - member-investor durable store    (onboarding fanout records)
    10| *   - fallback member store            (Supabase email-rate-limit fallback)
    11| *
    12| * Dedupe order: auth_user_id → landing_submission_id → email (lower) → phone digits.
    13| * Reads/writes via Supabase REST with the service-role key. Never fabricates data.
    14| */
    15|
    16|const DEPLOYMENT_MARKER = 'ivx-canonical-members-v1';
    17|
    18|export interface CanonicalMemberInput {
    19|  fullName?: string;
    20|  email?: string;
    21|  phone?: string;
    22|  memberType?: string;
    23|  source?: string;
    24|  sourceDetail?: string;
    25|  verificationStatus?: string;
    26|  smsVerified?: boolean;
    27|  emailVerified?: boolean;
    28|  investorInterest?: string;
    29|  preferredZipcode?: string;
    30|  budgetRange?: string;
    31|  authUserId?: string;
    32|  landingSubmissionId?: string;
    33|  pictureUrl?: string;
    34|  createdAt?: string;
    35|}
    36|
    37|export interface CanonicalMemberRow {
    38|  member_id: string;
    39|  full_name: string;
    40|  email: string;
    41|  phone: string;
    42|  member_type: string;
    43|  source: string;
    44|  source_detail: string;
    45|  verification_status: string;
    46|  sms_verified: boolean;
    47|  email_verified: boolean;
    48|  investor_interest: string;
    49|  preferred_zipcode: string;
    50|  budget_range: string;
    51|  picture_url: string;
    52|  auth_user_id: string | null;
    53|  landing_submission_id: string | null;
    54|  created_at: string;
    55|  updated_at: string;
    56|}
    57|
    58|export interface BackfillResult {
    59|  ok: boolean;
    60|  totalSourceRecords: number;
    61|  alreadySynced: number;
    62|  newlySynced: number;
    63|  duplicatesSkipped: number;
    64|  failed: number;
    65|  failures: { source: string; identifier: string; error: string }[];
    66|  perSource: Record<string, number>;
    67|  membersBefore: number;
    68|  membersAfter: number;
    69|  deploymentMarker: string;
    70|}
    71|
    72|function getSupabaseUrl(): string {
    73|  return (process.env.SUPABASE_URL || process.env.EXPO_PUBLIC_SUPABASE_URL || '').replace(/\/$/, '');
    74|}
    75|
    76|function getServiceKey(): string {
    77|  return (
    78|    process.env.SUPABASE_SERVICE_ROLE_KEY ||
    79|    process.env.SUPABASE_SERVICE_KEY ||
    80|    process.env.SUPABASE_ANON_KEY ||
    81|    process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY ||
    82|    ''
    83|  );
    84|}
    85|
    86|export function isCanonicalMembersConfigured(): boolean {
    87|  return Boolean(getSupabaseUrl() && getServiceKey());
    88|}
    89|
    90|function headers(prefer?: string): Record<string, string> {
    91|  const key = getServiceKey();
    92|  const h: Record<string, string> = {
    93|    apikey: key,
    94|    Authorization: `Bearer ${key}`,
    95|    'Content-Type': 'application/json',
    96|  };
    97|  if (prefer) h.Prefer = prefer;
    98|  return h;
    99|}
   100|
   101|async function rest<T>(pathName: string, init: RequestInit = {}, prefer?: string): Promise<T> {
   102|  const response = await fetch(`${getSupabaseUrl()}/rest/v1${pathName}`, {
   103|    ...init,
   104|    headers: { ...headers(prefer), ...(init.headers ?? {}) },
   105|  });
   106|  const text = await response.text();
   107|  let payload: unknown = null;
   108|  try { payload = text ? JSON.parse(text) : null; } catch { payload = text; }
   109|  if (!response.ok) {
   110|    const message =
   111|      payload && typeof payload === 'object'
   112|        ? String((payload as Record<string, unknown>).message ?? (payload as Record<string, unknown>).error ?? `HTTP ${response.status}`)
   113|        : `HTTP ${response.status}`;
   114|    throw new Error(`Supabase members REST ${response.status}: ${message}`);
   115|  }
   116|  return payload as T;
   117|}
   118|
   119|function normEmail(value: unknown): string {
   120|  return typeof value === 'string' ? value.trim().toLowerCase() : '';
   121|}
   122|
   123|function normPhoneDigits(value: unknown): string {
   124|  return typeof value === 'string' ? value.replace(/\D/g, '') : '';
   125|}
   126|
   127|function nowIso(): string {
   128|  return new Date().toISOString();
   129|}
   130|
   131|const VALID_MEMBER_TYPES = new Set([
   132|  'member', 'investor', 'buyer', 'realtor', 'influencer', 'jv_partner',
   133|  'seller', 'builder', 'developer', 'lender', 'land_owner', 'broker', 'owner',
   134|  'jv_deals', 'tokenized',
   135|]);
   136|
   137|function normalizeMemberType(value: unknown): string {
   138|  const raw = typeof value === 'string' ? value.trim().toLowerCase() : '';
   139|  if (VALID_MEMBER_TYPES.has(raw)) return raw === 'broker' ? 'realtor' : raw === 'developer' ? 'builder' : raw;
   140|  return 'member';
   141|}
   142|
   143|async function findExisting(input: CanonicalMemberInput): Promise<CanonicalMemberRow | null> {
   144|  const authUserId = (input.authUserId || '').trim();
   145|  if (authUserId) {
   146|    const rows = await rest<CanonicalMemberRow[]>(`/members?auth_user_id=eq.${encodeURIComponent(authUserId)}&limit=1`);
   147|    if (rows.length > 0) return rows[0];
   148|  }
   149|  const landingSubmissionId = (input.landingSubmissionId || '').trim();
   150|  if (landingSubmissionId) {
   151|    const rows = await rest<CanonicalMemberRow[]>(`/members?landing_submission_id=eq.${encodeURIComponent(landingSubmissionId)}&limit=1`);
   152|    if (rows.length > 0) return rows[0];
   153|  }
   154|  const email = normEmail(input.email);
   155|  if (email) {
   156|    const rows = await rest<CanonicalMemberRow[]>(`/members?email=ilike.${encodeURIComponent(email)}&limit=1`);
   157|    if (rows.length > 0) return rows[0];
   158|  }
   159|  const phoneDigits = normPhoneDigits(input.phone);
   160|  if (phoneDigits.length >= 10) {
   161|    const rows = await rest<CanonicalMemberRow[]>(`/members?phone=like.*${encodeURIComponent(phoneDigits.slice(-10))}&limit=1`);
   162|    if (rows.length > 0) return rows[0];
   163|  }
   164|  return null;
   165|}
