   167|/**
   168| * Insert or merge one canonical member. Returns the row plus whether it was
   169| * created, updated, or skipped (existing row already had all incoming data).
   170| */
   171|export async function upsertCanonicalMember(
   172|  input: CanonicalMemberInput
   173|): Promise<{ ok: boolean; action: 'created' | 'updated' | 'skipped'; member?: CanonicalMemberRow; error?: string }> {
   174|  if (!isCanonicalMembersConfigured()) {
   175|    return { ok: false, action: 'skipped', error: 'Supabase credentials missing' };
   176|  }
   177|  const email = normEmail(input.email);
   178|  const phone = (input.phone || '').trim();
   179|  if (!email && normPhoneDigits(phone).length < 10 && !(input.authUserId || '').trim()) {
   180|    return { ok: false, action: 'skipped', error: 'No dedupe identity (email/phone/auth user id)' };
   181|  }
   182|
   183|  try {
   184|    const existing = await findExisting(input);
   185|    const createdAt = input.createdAt && !Number.isNaN(new Date(input.createdAt).getTime())
   186|      ? new Date(input.createdAt).toISOString()
   187|      : nowIso();
   188|
   189|    if (!existing) {
   190|      const inserted = await rest<CanonicalMemberRow[]>(
   191|        '/members',
   192|        {
   193|          method: 'POST',
   194|          body: JSON.stringify({
   195|            full_name: (input.fullName || '').trim(),
   196|            email,
   197|            phone,
   198|            member_type: normalizeMemberType(input.memberType),
   199|            source: (input.source || 'landing_page').trim() || 'landing_page',
   200|            source_detail: (input.sourceDetail || '').trim(),
   201|            verification_status: (input.verificationStatus || 'unverified').trim() || 'unverified',
   202|            sms_verified: Boolean(input.smsVerified),
   203|            email_verified: Boolean(input.emailVerified),
   204|            investor_interest: (input.investorInterest || '').trim(),
   205|            preferred_zipcode: (input.preferredZipcode || '').trim(),
   206|            budget_range: (input.budgetRange || '').trim(),
   207|            picture_url: (input.pictureUrl || '').trim(),
   208|            auth_user_id: (input.authUserId || '').trim() || null,
   209|            landing_submission_id: (input.landingSubmissionId || '').trim() || null,
   210|            created_at: createdAt,
   211|            updated_at: nowIso(),
   212|          }),
   213|        },
   214|        'return=representation'
   215|      );
   216|      return { ok: true, action: 'created', member: inserted[0] };
   217|    }
   218|
   219|    // Merge: only fill blanks / upgrade flags; never blank out real data.
   220|    const patch: Record<string, unknown> = {};
   221|    if (!existing.full_name && (input.fullName || '').trim()) patch.full_name = (input.fullName || '').trim();
   222|    if (!existing.email && email) patch.email = email;
   223|    if (!existing.phone && phone) patch.phone = phone;
   224|    if (existing.member_type === 'member' && normalizeMemberType(input.memberType) !== 'member') {
   225|      patch.member_type = normalizeMemberType(input.memberType);
   226|    }
   227|    if (!existing.source_detail && (input.sourceDetail || '').trim()) patch.source_detail = (input.sourceDetail || '').trim();
   228|    if (!existing.investor_interest && (input.investorInterest || '').trim()) patch.investor_interest = (input.investorInterest || '').trim();
   229|    if (!existing.preferred_zipcode && (input.preferredZipcode || '').trim()) patch.preferred_zipcode = (input.preferredZipcode || '').trim();
   230|    if (!existing.budget_range && (input.budgetRange || '').trim()) patch.budget_range = (input.budgetRange || '').trim();
   231|    if (!existing.picture_url && (input.pictureUrl || '').trim()) patch.picture_url = (input.pictureUrl || '').trim();
   232|    if (!existing.auth_user_id && (input.authUserId || '').trim()) patch.auth_user_id = (input.authUserId || '').trim();
   233|    if (!existing.landing_submission_id && (input.landingSubmissionId || '').trim()) patch.landing_submission_id = (input.landingSubmissionId || '').trim();
   234|    if (input.smsVerified === true && !existing.sms_verified) patch.sms_verified = true;
   235|    if (input.emailVerified === true && !existing.email_verified) patch.email_verified = true;
   236|    if (input.verificationStatus && input.verificationStatus !== 'unverified' && existing.verification_status === 'unverified') {
   237|      patch.verification_status = input.verificationStatus;
   238|    }
   239|    const existingCreated = new Date(existing.created_at).getTime();
   240|    if (new Date(createdAt).getTime() < existingCreated) patch.created_at = createdAt;
   241|
   242|    if (Object.keys(patch).length === 0) {
   243|      return { ok: true, action: 'skipped', member: existing };
   244|    }
   245|    patch.updated_at = nowIso();
   246|    const updated = await rest<CanonicalMemberRow[]>(
   247|      `/members?member_id=eq.${encodeURIComponent(existing.member_id)}`,
   248|      { method: 'PATCH', body: JSON.stringify(patch) },
   249|      'return=representation'
   250|    );
   251|    return { ok: true, action: 'updated', member: updated[0] ?? existing };
   252|  } catch (error) {
   253|    const message = error instanceof Error ? error.message : 'unknown error';
   254|    console.error('[CanonicalMembers] Upsert failed:', message);
   255|    return { ok: false, action: 'skipped', error: message };
   256|  }
   257|}
   258|
   259|/** Mark verification flags on the canonical row for an auth user or email. */
   260|export async function markCanonicalMemberVerified(
   261|  identity: { authUserId?: string; email?: string },
   262|  flags: { smsVerified?: boolean; emailVerified?: boolean }
   263|): Promise<void> {
   264|  if (!isCanonicalMembersConfigured()) return;
   265|  try {
   266|    const existing = await findExisting({ authUserId: identity.authUserId, email: identity.email });
   267|    if (!existing) return;
   268|    const patch: Record<string, unknown> = { updated_at: nowIso() };
   269|    if (flags.smsVerified) patch.sms_verified = true;
   270|    if (flags.emailVerified) patch.email_verified = true;
   271|    const smsOk = flags.smsVerified || existing.sms_verified;
   272|    const emailOk = flags.emailVerified || existing.email_verified;
   273|    patch.verification_status = smsOk && emailOk ? 'verified' : (smsOk || emailOk ? 'partially_verified' : existing.verification_status);
   274|    await rest(`/members?member_id=eq.${encodeURIComponent(existing.member_id)}`, {
   275|      method: 'PATCH',
   276|      body: JSON.stringify(patch),
   277|    }, 'return=minimal');
   278|  } catch (error) {
   279|    console.error('[CanonicalMembers] Verify flag update failed:', error instanceof Error ? error.message : error);
   280|  }
   281|}
   282|
   283|export interface ListMembersOptions {
   284|  search?: string;
   285|  memberType?: string;
   286|  verified?: 'verified' | 'unverified' | 'sms_verified' | 'all';
   287|  limit?: number;
   288|}
   289|
   290|export async function listCanonicalMembers(options: ListMembersOptions = {}): Promise<CanonicalMemberRow[]> {
   291|  if (!isCanonicalMembersConfigured()) return [];
   292|  const limit = Math.min(Math.max(options.limit ?? 1000, 1), 2000);
   293|  let query = `/members?select=*&order=created_at.desc&limit=${limit}`;
   294|  const type = normalizeMemberType(options.memberType);
   295|  if (options.memberType && options.memberType !== 'all') query += `&member_type=eq.${encodeURIComponent(type)}`;
   296|  if (options.verified === 'verified') query += `&verification_status=eq.verified`;
   297|  if (options.verified === 'unverified') query += `&verification_status=eq.unverified`;
   298|  if (options.verified === 'sms_verified') query += `&sms_verified=is.true`;
   299|  const search = (options.search || '').trim();
   300|  if (search) {
   301|    const term = encodeURIComponent(`%${search}%`);
   302|    query += `&or=(full_name.ilike.${term},email.ilike.${term},phone.ilike.${term})`;
   303|  }
   304|  try {
   305|    return await rest<CanonicalMemberRow[]>(query);
   306|  } catch (error) {
   307|    console.error('[CanonicalMembers] List failed:', error instanceof Error ? error.message : error);
   308|    return [];
   309|  }
   310|}
   311|
   312|export async function countCanonicalMembers(): Promise<number> {
   313|  if (!isCanonicalMembersConfigured()) return 0;
   314|  try {
   315|    const response = await fetch(`${getSupabaseUrl()}/rest/v1/members?select=member_id`, {
   316|      method: 'HEAD',
   317|      headers: { ...headers('count=exact'), Range: '0-0' },
   318|    });
   319|    const range = response.headers.get('content-range') || '';
   320|    const total = range.split('/')[1];
   321|    return total && total !== '*' ? Number(total) : 0;
   322|  } catch {
   323|    return 0;
   324|  }
   325|}
