   337|async function collectAuthUsers(records: SourceRecord[]): Promise<void> {
   338|  const response = await fetch(`${getSupabaseUrl()}/auth/v1/admin/users?per_page=200`, { headers: headers() });
   339|  if (!response.ok) throw new Error(`auth admin users HTTP ${response.status}`);
   340|  const payload = (await response.json()) as { users?: Record<string, unknown>[] } | Record<string, unknown>[];
   341|  const users = Array.isArray(payload) ? payload : payload.users ?? [];
   342|  for (const user of users) {
   343|    const meta = (user.user_metadata ?? {}) as Record<string, unknown>;
   344|    const appMeta = (user.app_metadata ?? {}) as Record<string, unknown>;
   345|    const email = normEmail(user.email);
   346|    const fullName = [meta.first_name, meta.last_name].map((v) => (typeof v === 'string' ? v.trim() : '')).filter(Boolean).join(' ');
   347|    const roleInterests = Array.isArray(meta.role_interests) ? meta.role_interests.map(String) : [];
   348|    records.push({
   349|      source: 'auth.users',
   350|      identifier: email || String(user.id),
   351|      input: {
   352|        fullName,
   353|        email,
   354|        phone: typeof meta.phone === 'string' ? meta.phone : (typeof user.phone === 'string' ? user.phone : ''),
   355|        memberType: typeof appMeta.role === 'string' && appMeta.role === 'owner' ? 'owner' : (roleInterests[0] || 'member'),
   356|        source: 'landing_page',
   357|        sourceDetail: 'auth.users backfill',
   358|        emailVerified: Boolean(user.email_confirmed_at),
   359|        smsVerified: Boolean(user.phone_confirmed_at),
   360|        verificationStatus: user.email_confirmed_at ? 'partially_verified' : 'unverified',
   361|        investorInterest: roleInterests.join(', '),
   362|        preferredZipcode: typeof meta.zip_code === 'string' ? meta.zip_code : '',
   363|        authUserId: String(user.id),
   364|        createdAt: typeof user.created_at === 'string' ? user.created_at : undefined,
   365|      },
   366|    });
   367|  }
   368|}
   369|
   370|async function collectProfiles(records: SourceRecord[]): Promise<void> {
   371|  const rows = await rest<Record<string, unknown>[]>('/profiles?select=*&limit=1000');
   372|  for (const row of rows) {
   373|    const email = normEmail(row.email);
   374|    records.push({
   375|      source: 'profiles',
   376|      identifier: email || String(row.id),
   377|      input: {
   378|        fullName: [row.first_name, row.last_name].map((v) => (typeof v === 'string' ? v.trim() : '')).filter(Boolean).join(' '),
   379|        email,
   380|        phone: typeof row.phone === 'string' ? row.phone : '',
   381|        memberType: typeof row.role === 'string' ? row.role : 'member',
   382|        source: 'landing_page',
   383|        sourceDetail: 'profiles backfill',
   384|        authUserId: typeof row.id === 'string' && /^[0-9a-f-]{36}$/i.test(row.id) ? row.id : undefined,
   385|        createdAt: typeof row.created_at === 'string' ? row.created_at : undefined,
   386|      },
   387|    });
   388|  }
   389|}
   390|
   391|async function collectWaitlist(records: SourceRecord[]): Promise<void> {
   392|  const rows = await rest<Record<string, unknown>[]>('/waitlist?select=*&order=created_at.asc&limit=2000');
   393|  for (const row of rows) {
   394|    const email = normEmail(row.email);
   395|    if (!email) continue;
   396|    records.push({
   397|      source: 'waitlist',
   398|      identifier: email,
   399|      input: {
   400|        fullName: typeof row.name === 'string' ? row.name.trim() : '',
   401|        email,
   402|        memberType: 'member',
   403|        source: 'landing_page',
   404|        sourceDetail: `waitlist${typeof row.source === 'string' && row.source ? `:${row.source}` : ''}`,
   405|        landingSubmissionId: typeof row.id === 'string' ? `waitlist-${row.id}` : undefined,
   406|        createdAt: typeof row.created_at === 'string' ? row.created_at : undefined,
   407|      },
   408|    });
   409|  }
   410|}
   411|
   412|async function collectCapturedLeads(records: SourceRecord[]): Promise<void> {
   413|  const { listLeads } = await import('./ivx-lead-capture-store');
   414|  const leads = await listLeads();
   415|  for (const lead of leads) {
   416|    const email = normEmail(lead.email);
   417|    const phoneDigits = normPhoneDigits(lead.phone);
   418|    if (!email && phoneDigits.length < 10) continue;
   419|    records.push({
