   428|        sourceDetail: `lead_capture:${lead.id}${lead.sourceDetail ? ` (${lead.sourceDetail})` : ''}`,
   429|        investorInterest: lead.dealInterest || '',
   430|        budgetRange: lead.budgetRange || '',
   431|        preferredZipcode: lead.preferredMarket || '',
   432|        landingSubmissionId: lead.id,
   433|        createdAt: lead.createdAt,
