   439|async function collectMemberInvestorStore(records: SourceRecord[]): Promise<void> {
   440|  const { readDurableJson, isDurableStoreConfigured } = await import('./ivx-durable-store');
   441|  if (!isDurableStoreConfigured()) return;
   442|  const path = await import('node:path');
   443|  const file = path.join(process.cwd(), 'logs', 'audit', 'member-investor', 'members.json');
   444|  const members = await readDurableJson<Record<string, unknown>[]>(file, []);
   445|  for (const member of members) {
   446|    const email = normEmail(member.email);
   447|    if (!email) continue;
   448|    const roles = Array.isArray(member.roles) ? member.roles.map(String) : [];
   449|    records.push({
   450|      source: 'member_investor_store',
   451|      identifier: email,
   452|      input: {
   453|        fullName: [member.firstName, member.lastName].map((v) => (typeof v === 'string' ? v.trim() : '')).filter(Boolean).join(' '),
   454|        email,
   455|        phone: typeof member.phone === 'string' ? member.phone : '',
   456|        memberType: roles[0] || 'member',
   457|        source: 'landing_page',
   458|        sourceDetail: 'member_investor_store backfill',
   459|        investorInterest: roles.join(', '),
   460|        preferredZipcode: typeof member.zipCode === 'string' ? member.zipCode : '',
   461|        authUserId: typeof member.userId === 'string' && /^[0-9a-f-]{36}$/i.test(member.userId) ? member.userId : undefined,
   462|        createdAt: typeof member.createdAt === 'string' ? member.createdAt : undefined,
   463|      },
   464|    });
   465|  }
   466|}
