   468|async function collectFallbackMembers(records: SourceRecord[]): Promise<void> {
   469|  const { readDurableJson, isDurableStoreConfigured } = await import('./ivx-durable-store');
   470|  if (!isDurableStoreConfigured()) return;
   471|  const path = await import('node:path');
   472|  const file = path.join(process.cwd(), 'logs', 'audit', 'member-database', 'fallback-members.json');
   473|  const store = await readDurableJson<Record<string, Record<string, unknown>>>(file, {});
   474|  for (const member of Object.values(store)) {
   475|    const email = normEmail(member.email);
   476|    if (!email) continue;
   477|    records.push({
   478|      source: 'fallback_member_store',
   479|      identifier: email,
   480|      input: {
