   614|/**
   615| * Create a single-use enterprise invitation.
   616| * Only enterprise owners and administrators can invite.
   617| */
   618|export async function createInvitation(
   619|  input: InvitationInput
   620|): Promise<InvitationResult> {
   621|  const traceId = generateTraceId();
   622|  const supabase = getSupabaseAdmin();
   623|
   624|  // Validate
   625|  if (!input.enterpriseId) {
   626|    return { ok: false, errorCode: 'INVALID_INPUT', error: 'Enterprise ID is required.', traceId };
   627|  }
   628|  if (!input.invitedByAuthUserId) {
   629|    return { ok: false, errorCode: 'NOT_AUTHORIZED', error: userMessageForCode('NOT_AUTHORIZED'), traceId };
   630|  }
   631|  if (!isValidEmail(input.invitedEmail)) {
   632|    return { ok: false, errorCode: 'INVALID_INPUT', error: 'A valid invited email is required.', traceId };
   633|  }
   634|  if (!INVITABLE_ROLES.includes(input.enterpriseRole)) {
   635|    return { ok: false, errorCode: 'ROLE_NOT_ALLOWED', error: 'Cannot invite someone as owner. Use transfer ownership instead.', traceId };
   636|  }
   637|
   638|  // Check inviter is owner or administrator of this enterprise
   639|  const { data: inviterMembership } = await supabase
   640|    .from('enterprise_memberships')
   641|    .select('membership_id, enterprise_role, status')
   642|    .eq('enterprise_id', input.enterpriseId)
   643|    .eq('auth_user_id', input.invitedByAuthUserId)
   644|    .eq('status', 'active')
   645|    .limit(1);
   646|
   647|  if (!inviterMembership || inviterMembership.length === 0) {
   648|    return { ok: false, errorCode: 'NOT_AUTHORIZED', error: 'You are not a member of this enterprise.', traceId };
   649|  }
   650|
   651|  const inviterRole = inviterMembership[0].enterprise_role;
   652|  if (inviterRole !== 'owner' && inviterRole !== 'administrator') {
   653|    return { ok: false, errorCode: 'NOT_AUTHORIZED', error: 'Only owners and administrators can send invitations.', traceId };
   654|  }
   655|
   656|  // Administrators cannot invite other administrators (only owner can)
   657|  if (inviterRole === 'administrator' && input.enterpriseRole === 'administrator') {
   658|    return { ok: false, errorCode: 'ROLE_NOT_ALLOWED', error: 'Administrators cannot invite other administrators. Only the owner can.', traceId };
   659|  }
   660|
   661|  // Check for existing active membership for this email
   662|  const invitedEmail = normalizeEmail(input.invitedEmail);
   663|  const { data: existingMember } = await supabase
   664|    .from('enterprise_memberships')
   665|    .select('membership_id, status, auth_user_id')
   666|    .eq('enterprise_id', input.enterpriseId)
   667|    .neq('status', 'removed')
   668|    .limit(100);
   669|
   670|  // Check if any existing member has this email (we'd need to join with auth for email, but we block by pending invitation)
   671|  const { data: existingPending } = await supabase
   672|    .from('enterprise_invitations')
   673|    .select('invitation_id, status')
   674|    .eq('enterprise_id', input.enterpriseId)
   675|    .eq('invited_email', invitedEmail)
   676|    .eq('status', 'pending')
   677|    .limit(1);
   678|
   679|  if (existingPending && existingPending.length > 0) {
   680|    return { ok: false, errorCode: 'MEMBERSHIP_EXISTS', error: 'An active invitation already exists for this email.', traceId };
   681|  }
   682|
   683|  // Generate token
   684|  const rawToken = generateInvitationToken();
   685|  const tokenHash = hashToken(rawToken);
   686|  const expiresAt = new Date(Date.now() + (input.expirationHours || 168) * 60 * 60 * 1000).toISOString(); // 7 days default
   687|
   688|  // Insert invitation
   689|  try {
   690|    const { data: invitation, error } = await supabase
   691|      .from('enterprise_invitations')
   692|      .insert({
   693|        enterprise_id: input.enterpriseId,
   694|        token_hash: tokenHash,
   695|        invited_email: invitedEmail,
   696|        enterprise_role: input.enterpriseRole,
   697|        invited_by: input.invitedByName,
   698|        invited_by_auth_user_id: input.invitedByAuthUserId,
   699|        status: 'pending',
   700|        expires_at: expiresAt,
   701|      })
   702|      .select('invitation_id')
   703|      .single();
   704|
   705|    if (error || !invitation) {
   706|      console.error('[EnterpriseReg] Invitation creation failed:', error?.message);
   707|      return { ok: false, errorCode: 'CREATION_FAILED', error: 'Could not create invitation.', traceId };
   708|    }
   709|
   710|    await writeAuditEvent({
   711|      traceId,
   712|      authUserId: input.invitedByAuthUserId,
   713|      enterpriseId: input.enterpriseId,
   714|      stage: 'invitation_created',
   715|      eventType: 'enterprise_invitation_created',
   716|      eventData: { invitedEmail, role: input.enterpriseRole, expiresAt },
   717|      ipAddress: input.ipAddress,
   718|      userAgent: input.userAgent,
   719|      success: true,
   720|    });
   721|
   722|    return {
   723|      ok: true,
   724|      invitationId: invitation.invitation_id,
   725|      token: rawToken,
   726|      expiresAt,
   727|      traceId,
   728|    };
   729|  } catch (err) {
   730|    console.error('[EnterpriseReg] Invitation creation exception:', err instanceof Error ? err.message : 'unknown');
   731|    return { ok: false, errorCode: 'UNKNOWN_ERROR', error: userMessageForCode('UNKNOWN_ERROR'), traceId };
   732|  }
