   735|/**
   736| * Accept an enterprise invitation.
   737| * Single-use: token hash must match, not expired, not revoked, not already accepted.
   738| */
   739|export async function acceptInvitation(
   740|  input: AcceptInvitationInput
   741|): Promise<AcceptInvitationResult> {
   742|  const traceId = generateTraceId();
   743|  const supabase = getSupabaseAdmin();
   744|
   745|  if (!input.token || !input.acceptingAuthUserId || !input.enterpriseId) {
   746|    return { ok: false, errorCode: 'INVALID_INPUT', error: 'Token, auth user ID, and enterprise ID are required.', traceId };
   747|  }
   748|
   749|  const tokenHash = hashToken(input.token);
   750|
   751|  // Find invitation by token hash
   752|  const { data: invitation, error: findError } = await supabase
   753|    .from('enterprise_invitations')
   754|    .select('invitation_id, enterprise_id, invited_email, enterprise_role, status, expires_at, accepted_at')
   755|    .eq('token_hash', tokenHash)
   756|    .limit(1)
   757|    .single();
   758|
   759|  if (findError || !invitation) {
   760|    await writeAuditEvent({
   761|      traceId,
   762|      authUserId: input.acceptingAuthUserId,
   763|      enterpriseId: input.enterpriseId,
   764|      stage: 'invitation_accept',
   765|      eventType: 'invitation_accept_failed',
   766|      eventData: { reason: 'token_invalid' },
   767|      ipAddress: input.ipAddress,
   768|      userAgent: input.userAgent,
   769|      success: false,
   770|      errorCode: 'INVITATION_TOKEN_INVALID',
   771|      errorMessage: 'Token hash not found',
   772|    });
   773|    return { ok: false, errorCode: 'INVITATION_TOKEN_INVALID', error: userMessageForCode('INVITATION_TOKEN_INVALID'), traceId };
   774|  }
   775|
   776|  // Check enterprise matches
   777|  if (!timingSafeCompare(invitation.enterprise_id, input.enterpriseId)) {
   778|    return { ok: false, errorCode: 'INVITATION_WRONG_ENTERPRISE', error: userMessageForCode('INVITATION_WRONG_ENTERPRISE'), traceId };
   779|  }
   780|
   781|  // Check status
   782|  if (invitation.status === 'accepted') {
   783|    return { ok: false, errorCode: 'INVITATION_ALREADY_ACCEPTED', error: userMessageForCode('INVITATION_ALREADY_ACCEPTED'), traceId };
   784|  }
   785|  if (invitation.status === 'revoked') {
   786|    return { ok: false, errorCode: 'INVITATION_REVOKED', error: userMessageForCode('INVITATION_REVOKED'), traceId };
   787|  }
   788|  if (invitation.status === 'expired' || new Date(invitation.expires_at).getTime() < Date.now()) {
   789|    // Mark as expired if not already
   790|    await supabase.from('enterprise_invitations').update({ status: 'expired' }).eq('invitation_id', invitation.invitation_id);
   791|    return { ok: false, errorCode: 'INVITATION_EXPIRED', error: userMessageForCode('INVITATION_EXPIRED'), traceId };
   792|  }
   793|
   794|  // Check email matches
   795|  const expectedEmail = normalizeEmail(input.acceptingEmail);
   796|  if (!timingSafeCompare(normalizeEmail(invitation.invited_email), expectedEmail)) {
   797|    return { ok: false, errorCode: 'INVITATION_TOKEN_INVALID', error: 'This invitation was sent to a different email address.', traceId };
   798|  }
   799|
   800|  // Check no existing active membership
   801|  const { data: existingMembership } = await supabase
   802|    .from('enterprise_memberships')
   803|    .select('membership_id, status')
   804|    .eq('enterprise_id', input.enterpriseId)
   805|    .eq('auth_user_id', input.acceptingAuthUserId)
   806|    .neq('status', 'removed')
   807|    .limit(1);
   808|
   809|  if (existingMembership && existingMembership.length > 0) {
   810|    return { ok: false, errorCode: 'MEMBERSHIP_EXISTS', error: userMessageForCode('MEMBERSHIP_EXISTS'), traceId };
   811|  }
   812|
   813|  // Create membership
   814|  try {
   815|    const { data: membership, error: membershipError } = await supabase
   816|      .from('enterprise_memberships')
   817|      .insert({
   818|        enterprise_id: input.enterpriseId,
   819|        member_id: input.acceptingMemberId || '',
   820|        auth_user_id: input.acceptingAuthUserId,
   821|        enterprise_role: invitation.enterprise_role,
   822|        status: 'active',
   823|        invited_by: 'invitation',
   824|        invitation_id: invitation.invitation_id,
   825|        joined_at: new Date().toISOString(),
   826|      })
   827|      .select('membership_id')
   828|      .single();
   829|
   830|    if (membershipError || !membership) {
   831|      console.error('[EnterpriseReg] Membership creation failed:', membershipError?.message);
   832|      return { ok: false, errorCode: 'MEMBERSHIP_FAILED', error: 'Could not create membership.', traceId };
   833|    }
   834|
   835|    // Mark invitation as accepted (single-use)
   836|    await supabase
   837|      .from('enterprise_invitations')
   838|      .update({
   839|        status: 'accepted',
   840|        accepted_at: new Date().toISOString(),
   841|        accepted_by_member_id: input.acceptingMemberId || null,
   842|        accepted_by_auth_user_id: input.acceptingAuthUserId,
   843|      })
   844|      .eq('invitation_id', invitation.invitation_id);
   845|
   846|    await writeAuditEvent({
   847|      traceId,
   848|      authUserId: input.acceptingAuthUserId,
   849|      memberId: input.acceptingMemberId,
   850|      enterpriseId: input.enterpriseId,
   851|      stage: 'invitation_accepted',
   852|      eventType: 'enterprise_invitation_accepted',
   853|      eventData: { role: invitation.enterprise_role, invitationId: invitation.invitation_id },
   854|      ipAddress: input.ipAddress,
   855|      userAgent: input.userAgent,
   856|      success: true,
   857|    });
   858|
   859|    return {
   860|      ok: true,
   861|      membershipId: membership.membership_id,
   862|      enterpriseId: input.enterpriseId,
   863|      enterpriseRole: invitation.enterprise_role as EnterpriseRole,
   864|      traceId,
   865|    };
   866|  } catch (err) {
   867|    console.error('[EnterpriseReg] Membership creation exception:', err instanceof Error ? err.message : 'unknown');
   868|    return { ok: false, errorCode: 'UNKNOWN_ERROR', error: userMessageForCode('UNKNOWN_ERROR'), traceId };
   869|  }
