   940|
   941|/**
   942| * Suspend, remove, reactivate, or transfer ownership of a member.
   943| */
   944|export async function manageMembership(
   945|  input: MembershipActionInput
   946|): Promise<{ ok: boolean; error?: string; errorCode?: EnterpriseErrorCode; traceId: string }> {
   947|  const traceId = generateTraceId();
   948|  const supabase = getSupabaseAdmin();
   949|
   950|  // Find the acting member's role
   951|  const { data: actingMember } = await supabase
   952|    .from('enterprise_memberships')
   953|    .select('membership_id, enterprise_role, status')
   954|    .eq('enterprise_id', input.enterpriseId)
   955|    .eq('auth_user_id', input.actingAuthUserId)
   956|    .eq('status', 'active')
   957|    .limit(1)
   958|    .single();
   959|
   960|  if (!actingMember) {
   961|    return { ok: false, errorCode: 'NOT_AUTHORIZED', error: 'You are not an active member of this enterprise.', traceId };
   962|  }
   963|
   964|  const actingRole = actingMember.enterprise_role as EnterpriseRole;
   965|
   966|  // Find the target member
   967|  const { data: targetMember } = await supabase
   968|    .from('enterprise_memberships')
   969|    .select('membership_id, auth_user_id, member_id, enterprise_role, status')
   970|    .eq('enterprise_id', input.enterpriseId)
   971|    .eq('member_id', input.memberId)
   972|    .limit(1)
   973|    .single();
   974|
   975|  if (!targetMember) {
   976|    return { ok: false, errorCode: 'NOT_FOUND', error: 'Target member not found in this enterprise.', traceId };
   977|  }
   978|
   979|  const targetRole = targetMember.enterprise_role as EnterpriseRole;
   980|  const now = new Date().toISOString();
   981|
   982|  switch (input.action) {
   983|    case 'suspend': {
   984|      // Only owner or admin can suspend; admin cannot suspend admin or owner
   985|      if (actingRole !== 'owner' && !(actingRole === 'administrator' && targetRole !== 'owner' && targetRole !== 'administrator')) {
   986|        return { ok: false, errorCode: 'NOT_AUTHORIZED', error: 'You cannot suspend this member.', traceId };
   987|      }
   988|      if (targetMember.status !== 'active') {
   989|        return { ok: false, errorCode: 'INVALID_INPUT', error: 'Member is not active.', traceId };
   990|      }
   991|      await supabase
   992|        .from('enterprise_memberships')
   993|        .update({ status: 'suspended', suspended_at: now })
   994|        .eq('membership_id', targetMember.membership_id);
   995|      break;
   996|    }
   997|    case 'remove': {
   998|      if (actingRole !== 'owner' && !(actingRole === 'administrator' && targetRole !== 'owner' && targetRole !== 'administrator')) {
   999|        return { ok: false, errorCode: 'NOT_AUTHORIZED', error: 'You cannot remove this member.', traceId };
  1000|      }
  1001|      if (targetRole === 'owner') {
  1002|        return { ok: false, errorCode: 'OWNER_TRANSFER_DENIED', error: 'Cannot remove the owner. Transfer ownership first.', traceId };
  1003|      }
  1004|      await supabase
  1005|        .from('enterprise_memberships')
  1006|        .update({ status: 'removed', removed_at: now })
  1007|        .eq('membership_id', targetMember.membership_id);
  1008|      break;
  1009|    }
  1010|    case 'reactivate': {
  1011|      if (actingRole !== 'owner' && actingRole !== 'administrator') {
  1012|        return { ok: false, errorCode: 'NOT_AUTHORIZED', error: 'Only owners and administrators can reactivate members.', traceId };
  1013|      }
  1014|      if (targetMember.status !== 'suspended') {
  1015|        return { ok: false, errorCode: 'INVALID_INPUT', error: 'Member is not suspended.', traceId };
  1016|      }
  1017|      await supabase
  1018|        .from('enterprise_memberships')
  1019|        .update({ status: 'active', suspended_at: null })
  1020|        .eq('membership_id', targetMember.membership_id);
  1021|      break;
  1022|    }
  1023|    case 'transfer_ownership': {
  1024|      if (actingRole !== 'owner') {
  1025|        return { ok: false, errorCode: 'OWNER_TRANSFER_DENIED', error: userMessageForCode('OWNER_TRANSFER_DENIED'), traceId };
  1026|      }
  1027|      if (!input.newOwnerId) {
  1028|        return { ok: false, errorCode: 'INVALID_INPUT', error: 'New owner member ID is required.', traceId };
  1029|      }
  1030|      if (input.memberId !== input.actingAuthUserId && targetMember.auth_user_id !== input.actingAuthUserId) {
  1031|        // The current owner transfers TO another member
  1032|      }
  1033|      // Demote current owner to administrator
  1034|      await supabase
