   397|      message: 'First name and last name are required.',
   398|      retryable: false,
   399|    });
   400|  }
   401|  if (!isValidEmail(normalizedEmail)) {
   402|    return makeError('INVALID_EMAIL', 'VALIDATING', traceId, registrationRequestId, { retryable: false });
   403|  }
   404|  const pwCheck = validatePasswordPolicy(input.password);
   405|  if (!pwCheck.valid) {
   406|    return makeError('WEAK_PASSWORD', 'VALIDATING', traceId, registrationRequestId, {
   407|      message: pwCheck.reason ?? 'Password does not meet requirements.',
   408|      retryable: false,
   409|    });
   410|  }
   411|  if (!input.acceptTerms) {
   412|    return makeError('UNKNOWN_ERROR', 'VALIDATING', traceId, registrationRequestId, {
