   423|      ok: true,
   424|      stage: 'COMPLETED',
   425|      registrationRequestId,
   426|      traceId,
   427|      authUserId: existing.authUserId,
   428|      email: normalizedEmail,
   429|      requiresVerification: false,
   430|      resumeToken: existing.registrationRequestId,
   431|    };
   432|  }
