    85|DECLARE
    86|  r RECORD;
    87|BEGIN
    88|  -- Drop ALL policies on conversation_participants
    89|  FOR r IN (SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'conversation_participants')
    90|  LOOP
    91|    EXECUTE format('DROP POLICY IF EXISTS %I ON public.conversation_participants', r.policyname);
    92|  END LOOP;
    93|  -- Drop ALL policies on conversations
    94|  FOR r IN (SELECT policyname FROM pg_policies WHERE schemaname = 'public' AND tablename = 'conversations')
    95|  LOOP
    96|    EXECUTE format('DROP POLICY IF EXISTS %I ON public.conversations', r.policyname);
    97|  END LOOP;
    98|  -- Drop ALL policies on messages
