   663|const VERIFICATION_SQL = `SELECT
   664|  t.tablename as table_name,
   665|  t.rowsecurity as rls_enabled,
   666|  (SELECT count(*) FROM pg_policies p WHERE p.schemaname = 'public' AND p.tablename = t.tablename) as policy_count
   667|FROM pg_tables t
   668|WHERE t.schemaname = 'public'
   669|ORDER BY t.tablename;`;
