   671|/** Split SQL into individual statements handling dollar-quoting and comments. */
   672|function splitSqlStatements(sql: string): string[] {
   673|  const statements: string[] = [];
   674|  let current = '';
   675|  let index = 0;
   676|  let inSingleQuote = false;
   677|  let inDoubleQuote = false;
   678|  let inLineComment = false;
   679|  let inBlockComment = false;
   680|  let dollarTag: string | null = null;
   681|
   682|  while (index < sql.length) {
   683|    const char = sql[index] ?? '';
   684|    const next = sql[index + 1] ?? '';
   685|
   686|    if (inLineComment) { current += char; index++; if (char === '\n') inLineComment = false; continue; }
   687|    if (inBlockComment) { if (char === '*' && next === '/') { current += '*/'; index += 2; inBlockComment = false; continue; } current += char; index++; continue; }
   688|    if (dollarTag) { if (sql.startsWith(dollarTag, index)) { current += dollarTag; index += dollarTag.length; dollarTag = null; continue; } current += char; index++; continue; }
   689|    if (inSingleQuote) { current += char; index++; if (char === "'" && next === "'") { current += next; index++; continue; } if (char === "'") inSingleQuote = false; continue; }
   690|    if (inDoubleQuote) { current += char; index++; if (char === '"') inDoubleQuote = false; continue; }
   691|    if (char === '-' && next === '-') { current += '--'; index += 2; inLineComment = true; continue; }
   692|    if (char === '/' && next === '*') { current += '/*'; index += 2; inBlockComment = true; continue; }
   693|    if (char === "'") { current += char; index++; inSingleQuote = true; continue; }
   694|    if (char === '"') { current += char; index++; inDoubleQuote = true; continue; }
   695|    if (char === '$') { const tag = sql.slice(index).match(/^\$[A-Za-z0-9_]*\$/); if (tag) { current += tag[0]; index += tag[0].length; dollarTag = tag[0]; continue; } }
   696|    if (char === ';') { const trimmed = current.trim(); if (trimmed) statements.push(trimmed); current = ''; index++; continue; }
   697|    current += char; index++;
   698|  }
   699|  const finalStmt = current.trim();
   700|  if (finalStmt) statements.push(finalStmt);
   701|  return statements;
   702|}
