   704|/** Get the Supabase service role key from env (configured on Render production). */
   705|function getServiceRoleKey(): string | null {
   706|  const key = readTrimmed(process.env.SUPABASE_SERVICE_ROLE_KEY) || readTrimmed(process.env.SUPABASE_SERVICE_KEY);
   707|  if (!key) return null;
   708|  // Verify it's not the anon key
   709|  const anonKey = readTrimmed(process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY);
   710|  if (key === anonKey) return null;
   711|  return key;
   712|}
   713|
   714|/** Get Supabase REST base URL from env. */
   715|function getSupabaseRestUrl(): string {
   716|  const url = readTrimmed(process.env.EXPO_PUBLIC_SUPABASE_URL) || readTrimmed(process.env.SUPABASE_URL);
   717|  if (!url) throw new Error('EXPO_PUBLIC_SUPABASE_URL is not configured.');
   718|  return url.replace(/\/+$/, '');
