   721|/** Execute SQL via Supabase REST RPC (ivx_exec_sql) using service role key. */
   722|async function executeSqlViaServiceRole(statements: string[]): Promise<{ executed: number; errors: string[] }> {
   723|  const serviceKey = getServiceRoleKey();
   724|  if (!serviceKey) {
   725|    throw new Error('No DB connection string and no SUPABASE_SERVICE_ROLE_KEY available for SQL execution.');
   726|  }
   727|  const restUrl = getSupabaseRestUrl();
   728|  let executed = 0;
   729|  const errors: string[] = [];
   730|
   731|  for (let i = 0; i < statements.length; i++) {
   732|    const stmt = statements[i] ?? '';
   733|    const response = await fetch(`${restUrl}/rest/v1/rpc/ivx_exec_sql`, {
   734|      method: 'POST',
   735|      headers: {
   736|        apikey: serviceKey,
   737|        Authorization: `Bearer ${serviceKey}`,
   738|        'Content-Type': 'application/json',
   739|      },
   740|      body: JSON.stringify({ sql_text: stmt }),
   741|    });
   742|    if (!response.ok) {
   743|      const text = await response.text();
   744|      // If ivx_exec_sql doesn't exist or permission denied, throw immediately
   745|      if (text.includes('does not exist') || text.includes('Could not find') || text.includes('permission denied')) {
   746|        throw new Error(`ivx_exec_sql unavailable: ${text.slice(0, 200)}`);
   747|      }
   748|      errors.push(`Statement ${i + 1}/${statements.length}: ${text.slice(0, 200)}`);
   749|    } else {
   750|      executed++;
   751|    }
   752|  }
   753|  return { executed, errors };
   754|}
