   803|    'imported_lenders', 'ipx_holdings', 'ipx_purchases', 'landing_deployments',
   804|    'landing_page_config', 'lender_sync_config', 'lender_sync_jobs', 'lender_sync_stats',
   805|    'market_index', 'nerve_center_sessions', 'nerve_center_module_metrics',
   806|    'nerve_center_funnel_snapshots', 'nerve_center_user_profiles',
   807|    'nerve_center_chat_intelligence_events', 're_engagement_triggers', 'resale_listings',
   808|    'retargeting_dashboard', 'search_discovery', 'synced_lenders', 'utm_analytics',
